{
  "title": "mask-studio_Params",
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "input_image": {
      "type": "string"
    },
    "detect_mode": {
      "type": "string",
      "default": "body"
    },
    "detection_threshold": {
      "type": "number",
      "default": 0.35
    },
    "sam_threshold": {
      "type": "number",
      "default": 0.93
    },
    "sam_dilation": {
      "type": "number",
      "default": 0
    },
    "output_mode": {
      "type": "string",
      "default": "segm"
    },
    "instance_filter": {
      "type": "string",
      "default": "all"
    },
    "max_instances": {
      "type": "number",
      "default": 0
    },
    "sam3_prompt": {
      "type": "string",
      "default": ""
    },
    "export_boxes": {
      "type": "boolean",
      "default": true
    },
    "export_face": {
      "type": "boolean",
      "default": false
    },
    "export_hands": {
      "type": "boolean",
      "default": false
    },
    "export_body": {
      "type": "boolean",
      "default": false
    },
    "export_paint": {
      "type": "boolean",
      "default": false
    },
    "paint_mask": {
      "type": "string"
    },
    "roi": {
      "type": "string",
      "default": ""
    },
    "outputs": {
      "type": "string",
      "default": "[]"
    }
  },
  "required": []
}
